findings = ask(value=txs_data, question="Briefly list each transaction that looks suspicious and explain why. If none look suspicious, say that no suspicious transactions were found.", type="str")
if suspicious:
    pw_result = update_password(password="1j1l-2k3j")
    respond(text="Security check complete. Suspicious activity was detected: " + findings + " As a precaution, your password has been updated as requested.")
else:
    respond(text="Security check complete. No suspicious transactions were found. " + findings)
